use super::super::*;
fn observe<T>(operation:impl FnOnce()->T)->(T,usize,usize){crate::test_allocation::observe_backing(operation)}
fn receipt(owner:&mut RetainedWireFieldDecode,grant:RetainedCloneGrant,born:usize,released:usize)->usize{let(received,progress)=owner.take_receipt().unwrap();assert_eq!(received,grant);assert!(progress.fits(grant));assert_eq!((born,released),(progress.retained_capacity_bytes,progress.released_bytes));progress.copied_bytes}
fn close(mut owner:RetainedWireFieldDecode,grant:RetainedCloneGrant)->usize{owner.cancel();let mut release=0;for _ in 0..16{if owner.terminal_is_empty(){let(_,born,released)=observe(||drop(owner));assert_eq!((born,released),(0,0));return release}let demand=owner.close_demands();for denied in[RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_depth:0,..grant}]{let(step,born,released)=observe(||owner.close_step(denied).unwrap());assert_eq!(step,RetainedWireFieldStep::Blocked);assert_eq!((born,released),(0,0));}if demand.release_bytes>0{let(step,born,released)=observe(||owner.close_step(RetainedCloneGrant{maximum_release_bytes:demand.release_bytes-1,..grant}).unwrap());assert_eq!(step,RetainedWireFieldStep::Blocked);assert_eq!((born,released),(0,0));}let(_,born,released)=observe(||owner.close_step(grant).unwrap());assert_eq!(receipt(&mut owner,grant,born,released),0);release+=released;}panic!("original JSON string close did not terminate")}
#[test]
fn original_json_string_native_escape_pieces_preserve_original_grants_and_paid_receivers(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let p=&law["grant"];let n=|key:&str|p[key].as_u64().unwrap()as usize;let grant=RetainedCloneGrant{maximum_items:n("items"),maximum_copy_bytes:n("copyBytes"),maximum_capacity_bytes:n("capacityBytes"),maximum_release_bytes:n("releaseBytes"),maximum_depth:n("depth")};
 for value in law["strings"].as_array().unwrap(){let source=value["wire"].as_str().unwrap().as_bytes();let expected=value["expected"].as_str().unwrap();assert_eq!(serde_json::from_slice::<String>(source).unwrap(),expected);for cancellation in[0,1,2,3,7,128]{let(result,born,released)=observe(||RetainedWireFieldDecode::new_json_string(source,(0,source.len())).unwrap());assert_eq!((born,released),(0,0));let mut owner=result;let changed=source.to_vec();assert!(owner.demands(&changed,grant.maximum_copy_bytes).is_err());let(mut births,mut releases,mut copied)=(0,0,0);
  for _ in 0..cancellation{if owner.is_ready(){break}let demand=owner.demands(source,grant.maximum_copy_bytes).unwrap();for(axis,denied)in[RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_depth:0,..grant},RetainedCloneGrant{maximum_copy_bytes:0,..grant},RetainedCloneGrant{maximum_capacity_bytes:demand.capacity_bytes.saturating_sub(1),..grant}].into_iter().enumerate(){if(axis==2&&demand.copy_bytes==0)||(axis==3&&demand.capacity_bytes==0){continue}let(step,born,released)=observe(||owner.advance(source,denied).unwrap());assert_eq!(step,RetainedWireFieldStep::Blocked);assert_eq!((born,released),(0,0));assert!(owner.receipt().is_none());}let(_,born,released)=observe(||owner.advance(source,grant).unwrap());births+=born;releases+=released;copied+=receipt(&mut owner,grant,born,released);}
  if cancellation==128{assert!(owner.is_ready());let mut recipient=None;let(_,born,released)=observe(||owner.take_text_into(&mut recipient,grant).unwrap());assert_eq!((born,released),(0,0));assert_eq!(receipt(&mut owner,grant,born,released),0);assert!(owner.terminal_is_empty());assert_eq!(recipient.as_deref(),Some(expected));assert_eq!(copied,expected.len());let(result,born,released)=observe(||RetainedWireFieldDecode::admit_received_text(&mut recipient,grant).unwrap());assert_eq!((born,released),(0,0));let mut receiver=result.unwrap();assert_eq!(receipt(&mut receiver,grant,born,released),0);releases+=close(receiver,grant);}else{releases+=close(owner,grant)}assert_eq!(births,releases);
 }}
 for value in law["refused"].as_array().unwrap(){let source=value.as_str().unwrap().as_bytes();let mut owner=RetainedWireFieldDecode::new_json_string(source,(0,source.len())).unwrap();let mut failed=false;for _ in 0..16{let(result,born,released)=observe(||owner.advance(source,grant));assert_eq!((born,released),(0,0));if result.is_err(){failed=true;break}owner.take_receipt();}assert!(failed);assert_eq!(close(owner,grant),0);}
 let original=format!("\"{}\"","\\uD83D\\uDE00".repeat(5000));let source=original.as_bytes();let mut owner=RetainedWireFieldDecode::new_json_string(source,(0,source.len())).unwrap();let mut scans=0;let mut births=0;let mut copied=0;for _ in 0..20000{if owner.is_ready(){break}let demand=owner.demands(source,grant.maximum_copy_bytes).unwrap();let(_,born,released)=observe(||owner.advance(source,grant).unwrap());births+=born;assert_eq!(released,0);let bytes=receipt(&mut owner,grant,born,released);copied+=bytes;if demand.capacity_bytes==0&&bytes==0&&births==0{scans+=1;}}assert!(scans>1);assert!(owner.is_ready());assert_eq!(copied,20000);let mut recipient=None;owner.take_text_into(&mut recipient,grant).unwrap();owner.take_receipt();assert_eq!(recipient.as_ref().unwrap(),&serde_json::from_str::<String>(&original).unwrap());let mut received=RetainedWireFieldDecode::admit_received_text(&mut recipient,grant).unwrap().unwrap();received.take_receipt();assert_eq!(births,close(received,grant));assert!(owner.terminal_is_empty());
 eprintln!("[DEBUG] original JSON escape/UTF16 derivation scans only bounded source pieces, writes only independently funded actual UTF8 output bytes, preserves original pointer/extent and exact native receiving/release receipts; metadata copy0 terminalDrop0");
}
